import{bV as o,aL as a,u as t,G as i}from"./chunks/framework.DvBUyM1S.js";const g=JSON.parse('{"title":"Learnings — 纠正 / 知识缺口 / 更好做法","description":"","frontmatter":{},"headers":[],"relativePath":"learnings/LEARNINGS.md","filePath":"learnings/LEARNINGS.md"}'),s={name:"learnings/LEARNINGS.md"};function d(l,e,r,c,n,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="learnings-—-纠正-知识缺口-更好做法" tabindex="-1">Learnings — 纠正 / 知识缺口 / 更好做法 <a class="header-anchor" href="#learnings-—-纠正-知识缺口-更好做法" aria-label="Permalink to &quot;Learnings — 纠正 / 知识缺口 / 更好做法&quot;">​</a></h1><blockquote><p>追加式分轨日志（id 前缀 <code>LRN</code>）。条目格式见 <a href="./../WORKFLOW">WORKFLOW.md</a> 第 4.2 节。 同一 Pattern 复现 ≥3 次（See Also 链接计数）应提炼为 playbook（WORKFLOW.md 第 6 节）。</p></blockquote><hr><h2 id="lrn-20260826-001-配置驱动组件的回落开关应绑定「功能是否启用」而非「配置是否有值」" tabindex="-1">[LRN-20260826-001] 配置驱动组件的回落开关应绑定「功能是否启用」而非「配置是否有值」 <a class="header-anchor" href="#lrn-20260826-001-配置驱动组件的回落开关应绑定「功能是否启用」而非「配置是否有值」" aria-label="Permalink to &quot;[LRN-20260826-001] 配置驱动组件的回落开关应绑定「功能是否启用」而非「配置是否有值」&quot;">​</a></h2><p><strong>Logged</strong>: 2026-08-26T14:29:27 | <strong>Status</strong>: resolved | <strong>Tags</strong>: vue, config-driven, fallback</p><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p><code>if (schema?.items?.length)</code> 式判断把「功能已启用但配置为空」误判成「功能未启用」，空配置被静默回落到代码里写死的默认行为；但空数组往往是接口契约里的合法业务语义，应作为最终态生效，而不是触发回落。</p><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>场景：通用表格组件接入运行期页面契约（接口返回 restricted + forms[].queries），契约生效但 queries 为空数组时，组件用 <code>schemaContract?.queries?.length</code> 决定是否走契约分支——空数组 falsy → 落回默认 search 注解，表现为「接口明确说没有查询项，页面却显示全部默认筛选字段」，且请求参数形态随之回落（结构化 conditions → 扁平参数）。</li><li>根因：一个布尔开关承载了两种语义——「契约未生效」与「契约生效但无查询项」是两个状态，<code>?.length</code> 把后者折叠进了前者。</li><li>接口文档已约定「queries 空数组 = 不展示查询区」，是实现违背了契约；排查这类&quot;接口返回空但 UI 不变&quot;问题，先查接口文档的空值语义，再查前端判断条件。</li></ul><h3 id="suggested-action" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><p>回落开关只绑定功能启用标志（<code>if (schemaContract.value)</code>），配置载荷另做空值兜底（<code>(queries || []).map</code>）；渲染与请求参数两处必须用同一开关，避免半回落状态；下游要有空字段列表的天然 no-op 路径（搜索区 v-if 不渲染、参数构造返回空对象）。</p><h3 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h3><p>2026-08-26 在 qcmV2 的 ProTable.vue 中将 allFields 与 getQueryParams 的判断从 <code>schemaContract.value?.queries?.length</code> 收敛为 <code>schemaContract.value</code>：queries 为空时不渲染搜索区、请求不带 conditions；组件 README 生效规则表同步补注。</p><hr><h2 id="lrn-20260826-002-jackson-序列化-key-与-spring-mvc-绑定-key-对连续大写开头字段不一致" tabindex="-1">[LRN-20260826-002] Jackson 序列化 key 与 Spring MVC 绑定 key 对连续大写开头字段不一致 <a class="header-anchor" href="#lrn-20260826-002-jackson-序列化-key-与-spring-mvc-绑定-key-对连续大写开头字段不一致" aria-label="Permalink to &quot;[LRN-20260826-002] Jackson 序列化 key 与 Spring MVC 绑定 key 对连续大写开头字段不一致&quot;">​</a></h2><p><strong>Logged</strong>: 2026-08-26T17:24:12 | <strong>Status</strong>: pending | <strong>Tags</strong>: jackson, spring, java-beans, binding <strong>See Also</strong>: PB-20260825-001</p><h3 id="summary-1" tabindex="-1">Summary <a class="header-anchor" href="#summary-1" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>Java 字段第二字符大写（如 <code>jAmsea</code>）且无 <code>@JsonProperty</code> 时，Jackson 序列化的响应 key（<code>jamsea</code>）与 Spring MVC GET 参数绑定期望的 key（<code>JAmsea</code>）是两个值，前端按响应 key 提交查询会静默绑定失败。</p><h3 id="details-1" tabindex="-1">Details <a class="header-anchor" href="#details-1" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>Jackson 对 getter <code>getJAmsea()</code> 按连续大写开头整体小写化 mangle → 响应 key <code>jamsea</code>；</li><li>Spring MVC 数据绑定走 JavaBeans <code>Introspector.decapitalize</code>：前两字符均大写时保留原名 → 绑定 key <code>JAmsea</code>；</li><li>两层规则差异在字段无显式 <code>@JsonProperty</code> 覆盖时暴露；</li><li>症状隐蔽：不报错不 500，仅查询条件不生效（QueryWrapperGenerator 反射取到 null 后跳过该条件）；</li><li>排查手段：对照实体 getter 推导两层 key；<code>git log</code> 确认历史上字段改名是否前后端同步。</li></ul><h3 id="suggested-action-1" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action-1" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><p>前端双 key 分离：提交 key 用 JavaBeans 属性名（<code>JAmsea</code>），显示 key 用序列化 key（<code>row.jamsea</code>）；或后端加 <code>@JsonProperty</code> 显式统一两层口径（需评估历史报文兼容）。</p><hr><h2 id="lrn-20260831-001-官方-tip-的-必须配置-要先用探针实测-再决定采纳" tabindex="-1">[LRN-20260831-001] 官方 TIP 的&quot;必须配置&quot;要先用探针实测，再决定采纳 <a class="header-anchor" href="#lrn-20260831-001-官方-tip-的-必须配置-要先用探针实测-再决定采纳" aria-label="Permalink to &quot;[LRN-20260831-001] 官方 TIP 的&quot;必须配置&quot;要先用探针实测，再决定采纳&quot;">​</a></h2><p><strong>Logged</strong>: 2026-08-31T17:00:00 | <strong>Status</strong>: resolved | <strong>Tags</strong>: docs, verification, pnpm, dayjs</p><h3 id="summary-2" tabindex="-1">Summary <a class="header-anchor" href="#summary-2" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>Element Plus 文档要求 pnpm 用户为 <code>dayjs</code> 配置依赖提升（<code>shamefullyHoist</code> + <code>nodeLinker: hoisted</code>）， 否则按需引入会出问题。实测（Vite 6 + pnpm 12）该问题<strong>根本不存在</strong>， 盲目照做反而会拍平 <code>node_modules</code>、丢掉 pnpm 的隔离优势。</p><h3 id="details-2" tabindex="-1">Details <a class="header-anchor" href="#details-2" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>场景：按官方 Quick Start 给模板接 Element Plus 按需引入，读到关于 dayjs 的 TIP；</li><li>该 TIP 措辞很硬（&quot;you need to configure pnpm to hoist dependencies&quot;）， 照做要改 <code>pnpm-workspace.yaml</code>，属于影响整个依赖布局的<strong>重型变更</strong>；</li><li>实测结果：<code>dayjs</code> 不在 package.json、不在顶层 node_modules（只在 <code>.pnpm/dayjs@1.11.23</code>）， 但被 Vite 内联进 <code>node_modules/.vite/deps/element-plus_es.js</code>（212 处命中）； 预构建产物 <code>require(</code> 计数 0，生产产物 <code>module.exports</code> 计数 0，<code>ElDatePicker</code> 样式请求正常；</li><li>结论：Vite 6 的 optimizeDeps 已能处理这个 CJS 传递依赖，TIP 是历史遗留建议；</li><li>反向代价：若真加 <code>shamefullyHoist: true</code> + <code>nodeLinker: hoisted</code>， <code>.pnpm</code> 隔离目录不再使用，此前&quot;靠 <code>.pnpm/&amp;lt;pkg&amp;gt;@&amp;lt;ver&amp;gt;/node_modules/</code> 判断依赖是否齐全&quot; 的排查手法会全部失效（见 ERR-20260831-005）。</li></ul><h3 id="suggested-action-2" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action-2" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><ol><li>读到文档里&quot;必须/需要配置 X&quot;的硬性要求，先评估 X 的<strong>破坏半径</strong>： 全局依赖布局、构建流程、类型系统这类重型变更，一律先实测再采纳；</li><li>设计最小探针直接验证问题是否存在（本次：搜产物里的 <code>dayjs</code> / <code>require(</code> / <code>module.exports</code>， 并 dev 下直接请求 <code>date-picker</code> 的样式模块）；</li><li>文档给的替代方案里，优先选<strong>局部、可逆</strong>的那个 （本次是 <code>pnpm add dayjs</code>，而非全局 hoist）；</li><li>把&quot;实测结论 + 适用版本&quot;写进项目注释，避免后来者重复踩或重复排查。</li></ol><h3 id="resolution-1" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-1" aria-label="Permalink to &quot;Resolution&quot;">​</a></h3><p>2026-08-31：未采纳 hoist 建议，也未加 dayjs 依赖（实测无必要）； 改为在 <code>README.md</code> / <code>README.zh-CN.md</code> 的按需加载章节记录实测数据与判断依据， 并指明&quot;若其他工具链真遇到问题，用 <code>pnpm add dayjs</code> 而非 <code>shamefullyHoist</code>&quot;。</p><p>See Also: PB-20260831-003, ERR-20260831-005</p><h2 id="lrn-20260903-001-组件能配置的效果不用-css-hack-先查安装版-api-再写-deep-覆盖" tabindex="-1">[LRN-20260903-001] 组件能配置的效果不用 CSS hack：先查安装版 API 再写 :deep 覆盖 <a class="header-anchor" href="#lrn-20260903-001-组件能配置的效果不用-css-hack-先查安装版-api-再写-deep-覆盖" aria-label="Permalink to &quot;[LRN-20260903-001] 组件能配置的效果不用 CSS hack：先查安装版 API 再写 :deep 覆盖&quot;">​</a></h2><p><strong>Logged</strong>: 2026-09-03T18:30:00 | <strong>Status</strong>: resolved | <strong>Tags</strong>: element-plus, css, vue <strong>See Also</strong>: PB-20260831-003</p><h3 id="summary-3" tabindex="-1">Summary <a class="header-anchor" href="#summary-3" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>Element Plus <code>el-descriptions</code> 标签列定宽需求，直接用 <code>:deep()</code> CSS 覆盖 label <code>td</code>，而安装版（2.14.3）已原生提供 <code>label-width</code> prop——border 模式下内部实现就是给 label <code>td</code> 写内联 <code>width</code>，两者完全等价；CSS 只应兜底组件未暴露的能力（如 <code>table-layout: fixed</code> 布局算法）。</p><h3 id="details-3" tabindex="-1">Details <a class="header-anchor" href="#details-3" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>场景：详情页 8 组 <code>el-descriptions</code> 需要「标签 200px + 内容列均分、组间纵向网格线对齐」；</li><li>原实现用 <code>:deep(.el-descriptions__table) td.el-descriptions__label { width: 200px }</code>；</li><li>核对安装版类型定义（description.d.ts / description-item.d.ts）：容器级 <code>labelWidth</code>（&quot;width of every label column&quot;）与 item 级 <code>labelWidth</code>（优先级更高）均已存在；</li><li>源码核对（descriptions-cell.mjs）：border 模式 <code>style.width = addUnit(labelWidth)</code> 直接落在 label <code>td</code> 上——与手写 CSS 等价，改配置零行为差异；</li><li><code>width: 100%</code> 也是冗余的：theme-chalk 默认样式 <code>.el-descriptions__table { width: 100% }</code> 已含；</li><li>组件确实未暴露的能力才保留 CSS：<code>table-layout: fixed</code>（列宽由首行决定——标签列吃 <code>label-width</code> 配置、内容列均分剩余宽度，多个独立 descriptions 表格用同一算法才能组间对齐；auto 布局各表格按内容独立算列宽，组间对不齐）与 <code>overflow-wrap: break-word</code>（fixed 格子内长文本断行兜底）。</li></ul><h3 id="suggested-action-3" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action-3" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><p>写 <code>:deep()</code> 覆盖前先翻<strong>安装版本</strong>的类型定义/源码确认有无对应 prop（配置可维护、被 TS 校验、随组件升级；CSS 覆盖绕过组件抽象，随版本漂移易碎）；覆盖只留组件 API 表达不了的部分，并注释说明「为什么必须用 CSS」。</p><h3 id="resolution-2" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-2" aria-label="Permalink to &quot;Resolution&quot;">​</a></h3><p>2026-09-03：商品主数据详情页改为 <code>:label-width=&quot;200&quot;</code> 配置，CSS 收敛为 <code>table-layout: fixed</code> + <code>overflow-wrap: break-word</code> 两项并注明配置边界；lint 门禁通过。</p><hr><h2 id="lrn-20260903-002-全局-page-是列表页专用固定高度容器-详情页误用导致内容被裁切" tabindex="-1">[LRN-20260903-002] 全局 <code>.page</code> 是列表页专用固定高度容器，详情页误用导致内容被裁切 <a class="header-anchor" href="#lrn-20260903-002-全局-page-是列表页专用固定高度容器-详情页误用导致内容被裁切" aria-label="Permalink to &quot;[LRN-20260903-002] 全局 `.page` 是列表页专用固定高度容器，详情页误用导致内容被裁切&quot;">​</a></h2><p><strong>Logged</strong>: 2026-09-03T19:30:00 | <strong>Status</strong>: resolved | <strong>Tags</strong>: css, layout, element-plus, vue <strong>See Also</strong>: LRN-20260903-001</p><h3 id="summary-4" tabindex="-1">Summary <a class="header-anchor" href="#summary-4" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>jp-ui 全局 <code>.page</code> class（app.scss）自带固定视口高度 <code>height: calc(100% - 16px)</code>（含 <code>!important</code> 变体），是列表页专用容器（内部靠 jp-table 自滚）；详情页把它当普通内容容器复用后，内容超长即被固定高度裁切，表现为「页面显示不全」。</p><h3 id="details-4" tabindex="-1">Details <a class="header-anchor" href="#details-4" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>场景：5 个详情页（MDP 商品/供应商、SCM 订单、BI 销售、PLM 样品）模板根节点都写了 <code>class=&quot;page p-4&quot;</code>，内容最长的商品主数据详情（8 组 el-descriptions + 3 个子表 tabs）最先暴露内容被截断；</li><li>根因：<code>.page</code> 的设计契约是「固定视口高度 + 内部表格区滚动」，详情页内容高度远超视口，容器自身又无滚动，溢出即被裁切；</li><li>滚动归属：布局层 <code>adminui-main</code> 是 <code>overflow: auto</code>，详情页容器只要高度自适应内容，整页滚动天然可用；</li><li>隐蔽性：列表页用 <code>.page</code> 一切正常，坑只在「内容超高页面」复用该 class 时暴露；全局样式里的 <code>!important</code> 高度变体更难排查。</li></ul><h3 id="suggested-action-4" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action-4" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><p>区分容器语义后再复用全局 class：固定视口高度容器（列表页 <code>.page</code>）只服务内部自滚的列表布局；详情页/长内容页用高度自适应容器，仅保留卡片外观（白底、圆角、margin、padding），滚动交给布局层；新增页面先判断「滚动归属在容器内还是布局层」再选容器 class，并在 scoped 样式里注释容器选型原因。</p><h3 id="resolution-3" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-3" aria-label="Permalink to &quot;Resolution&quot;">​</a></h3><p>2026-09-03：5 个详情页容器改为 <code>.detail-page p-4</code>（高度自适应 + 列表页同款白底卡片外观），容器样式随后按用户要求收敛至 app.scss 全局定义（各页 scoped 不再重复），页面注释指向全局；定向 eslint 门禁通过。</p><hr><h2 id="lrn-20260904-001-判断「某包离了-install-script-就跑不了」要先看它怎么定位原生二进制-别凭经验断言" tabindex="-1">[LRN-20260904-001] 判断「某包离了 install script 就跑不了」要先看它怎么定位原生二进制，别凭经验断言 <a class="header-anchor" href="#lrn-20260904-001-判断「某包离了-install-script-就跑不了」要先看它怎么定位原生二进制-别凭经验断言" aria-label="Permalink to &quot;[LRN-20260904-001] 判断「某包离了 install script 就跑不了」要先看它怎么定位原生二进制，别凭经验断言&quot;">​</a></h2><p><strong>Logged</strong>: 2026-09-04T20:10:00 | <strong>Status</strong>: resolved | <strong>Tags</strong>: pnpm, esbuild, install-scripts, verification <strong>See Also</strong>: PB-20260904-002, ERR-20260831-003</p><h3 id="summary-5" tabindex="-1">Summary <a class="header-anchor" href="#summary-5" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>我断言「<code>pnpm install --ignore-scripts</code> 会打断 esbuild → vite build 必挂」，实测是错的：esbuild 0.25 的 JS API 不走自己 <code>bin/esbuild</code>，而走 optionalDependencies 里的平台包 <code>@esbuild/&amp;lt;platform&amp;gt;/bin/esbuild</code>，跳过 postinstall 照样能构建。</p><h3 id="details-5" tabindex="-1">Details <a class="header-anchor" href="#details-5" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>触发：给 ding-h5 设计 CI 脚本，凭「esbuild 靠 postinstall 落地二进制」这条老经验判了死刑；</li><li>实测：<code>node_modules/esbuild/lib/main.js</code> 的 <code>generateBinPath()</code> 里是 <code>require.resolve(\\</code>${pkg}/${subpath}`)<code>（pkg = </code>@esbuild/win32-x64<code>，subpath = </code>bin/esbuild<code>，见 main.js:1691），与 esbuild 自身 </code>bin/<code>无关；把本地</code>node_modules/esbuild/bin/esbuild<code>改名后</code>transformSync` 仍成功；</li><li>老经验的来源：esbuild &lt;0.16 时代没有平台可选包，二进制靠 install.js 现下载，那时 <code>--ignore-scripts</code> 确实致命；0.16 之后已改为平台包分发；</li><li>全仓扫描确认（<code>node_modules/.pnpm/*/node_modules/*/package.json</code>）只有 3 个包带 install script：esbuild（CLI shim，非必需）、core-js（funder 提示）、simple-git-hooks（装 git hook，CI 里本就该跳过）——正好等于 <code>pnpm-workspace.yaml</code> 的 <code>allowBuilds</code> 白名单，所以 <code>--ignore-scripts</code> 在这类工程里是安全的。</li></ul><h3 id="suggested-action-5" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action-5" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><p>判定「必须跑 install script」时按三步走，不要直接下结论：① 读目标包的解析代码（找 <code>require.resolve</code> / <code>binPath</code>）；② 做一次可逆的破坏性验证（把产物改名再跑 API）；③ 必要时全仓扫一遍哪些包真有 install script，再看白名单是否覆盖。结论落到文档前必须有其一。</p><h3 id="resolution-4" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-4" aria-label="Permalink to &quot;Resolution&quot;">​</a></h3><p>2026-09-04：已实测推翻原判断，并把 PB-20260904-002 第 3 节从「<code>--ignore-scripts</code> 会打断 esbuild」改写为「用 allowBuilds 白名单替代全局禁脚本 / 何时可保留 <code>--ignore-scripts</code>」。</p><hr><h2 id="lrn-20260904-002-对抗式审查必须含「声明层」核对-任务清单勾了-x-功能已实现-后端接口就绪会制造已完成假象" tabindex="-1">[LRN-20260904-002] 对抗式审查必须含「声明层」核对：任务清单勾了 <code>[x]</code> ≠ 功能已实现，后端接口就绪会制造已完成假象 <a class="header-anchor" href="#lrn-20260904-002-对抗式审查必须含「声明层」核对-任务清单勾了-x-功能已实现-后端接口就绪会制造已完成假象" aria-label="Permalink to &quot;[LRN-20260904-002] 对抗式审查必须含「声明层」核对：任务清单勾了 `[x]` ≠ 功能已实现，后端接口就绪会制造已完成假象&quot;">​</a></h2><p><strong>Logged</strong>: 2026-09-04T21:30:00 | <strong>Status</strong>: resolved | <strong>Tags</strong>: adversarial-review, task-checklist, verification, openspec</p><h3 id="summary-6" tabindex="-1">Summary <a class="header-anchor" href="#summary-6" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>PRD→代码一致性审查中，最隐蔽的缺口不是「规格没写」也不是「代码没写」，而是<strong>任务清单标记完成但功能没实现</strong>：后端把接口做好了（能力就绪），前端没接线（消费端缺失），tasks.md 还打了勾——三层里任何单层核查都可能误判，必须交叉。</p><h3 id="details-6" tabindex="-1">Details <a class="header-anchor" href="#details-6" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>场景：补配业务族 PRD 对抗式审查（diff 基准 07e62c3 → HEAD，124 文件 +9130/-2752）。PRD 6 处明确要求「返修工具按分销商省份自动带出工厂」，spec L48 有 SHALL，tasks.md 4.3 标 <code>[x]</code>，后端 <code>factoryOptions(provinceCode)</code> 省份过滤已实现——但前端 <code>onAccessoryTypeChange()</code> 无联动、<code>loadFactoryOptions()</code> 固定传空参，且 roleContext 无省份数据源（想接也没数）。</li><li>三层假象链：只看任务清单→「做完了」；只看后端→「接口就绪随时能用」；只有从前端消费端反向验证（谁调了这个接口？参数从哪来？）才暴露缺口。</li><li>定级依据：因为 tasks 标记与实现不符，这不是普通漏做，而是违反「规格/代码/测试/验证记录一致」准绳的声明失真，直接定 P1。</li><li>归属分责手法：对每个问题文件跑 <code>git log &amp;lt;base&amp;gt;..HEAD -- &amp;lt;file&amp;gt;</code>，一次即可把全部问题精确归到具体 commit（本次全部指向 4ebd42f02 feat-011，而 feat-010 全清白）——比逐 commit diff 快且证据确凿。</li></ul><h3 id="suggested-action-6" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action-6" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><p>对抗式审查的固定流程里加一层「声明层核对」：① 逐条扫任务清单的 <code>[x]</code> 项，每项在前端消费端找调用证据（事件处理器/取数代码），找不到即降级为「声明与实现不符」；② 后端接口存在≠功能完成，以「谁调用它、参数从哪来」为判据；③ 发现此类缺口定级上浮一档（声明失真比单纯漏做危害大，会误导后续排期与交接）；④ 报告阶段用 <code>git log &amp;lt;base&amp;gt;..HEAD -- &amp;lt;file&amp;gt;</code> 把每个差距归属到 commit，让「哪一批交付有问题」一目了然。</p><h3 id="resolution-5" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-5" aria-label="Permalink to &quot;Resolution&quot;">​</a></h3><p>2026-09-04：QCM V2 补配审查按此法产出最终报告（P1×1/P2×2/P3×1/P4×4，其余 95% 一致），报告存档于项目 <code>文档/对抗式审查-补配业务族PRD实现一致性核对-20260904.md</code>，P1 修复待用户确认省份数据源后执行。</p><hr><h2 id="lrn-20260907-001-做统计-指标功能前-先验证源字段的真实取值分布——写入侧硬编码会让指标恒为常量" tabindex="-1">[LRN-20260907-001] 做统计 / 指标功能前，先验证源字段的真实取值分布——写入侧硬编码会让指标恒为常量 <a class="header-anchor" href="#lrn-20260907-001-做统计-指标功能前-先验证源字段的真实取值分布——写入侧硬编码会让指标恒为常量" aria-label="Permalink to &quot;[LRN-20260907-001] 做统计 / 指标功能前，先验证源字段的真实取值分布——写入侧硬编码会让指标恒为常量&quot;">​</a></h2><p><strong>Logged</strong>: 2026-09-07 | <strong>Status</strong>: resolved | <strong>Tags</strong>: metrics, statistics, data-quality, verification</p><h3 id="summary-7" tabindex="-1">Summary <a class="header-anchor" href="#summary-7" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>新增「调用统计」（调用量 / 成功率 / 耗时）时，最容易漏的不是聚合 SQL，而是<strong>源字段根本没被正确写入</strong>：日志拦截里 <code>statusFlag</code> 被硬编码成常量 0，聚合逻辑再正确，成功率也恒为 0%。统计类需求的验收要前移到「字段有没有真值」。</p><h3 id="details-7" tabindex="-1">Details <a class="header-anchor" href="#details-7" aria-label="Permalink to &quot;Details&quot;">​</a></h3><ul><li>场景：QCM V2 接口平台新增统计看板，按 <code>interface_api_log.statusFlag</code>（0 失败 / 1 成功 / 2 异常）算成功率。写完 SQL 回头核对写入侧，发现 <code>LogInterceptor</code> 里 <code>.statusFlag(0)</code> 是硬编码，全表无条件全写 0——成功率这个核心指标必然恒为 0。</li><li>为什么容易漏：需求是「统计」，注意力全在聚合与维度上；而字段的语义由注释/枚举定义（看起来是对的），真实取值分布却由<strong>写入侧代码</strong>决定，两者可能长期脱节且无人发现（因为此前没人消费这个字段）。</li><li>判定方法：动手写聚合前，先做一次「字段健康度检查」——① 全仓搜该字段的<strong>写入点</strong>（不是读取点）；② 看写入值是常量还是按结果计算；③ 有条件就按取值分组 count 一次看分布。任一步发现「唯一写入点是常量」，统计口径就得先修写入侧。</li><li>同类扩散：耗时字段（是否真算了差值）、来源字段（是否留空）、租户/应用标识（是否透传）同样适用。</li></ul><h3 id="suggested-action-7" tabindex="-1">Suggested Action <a class="header-anchor" href="#suggested-action-7" aria-label="Permalink to &quot;Suggested Action&quot;">​</a></h3><ol><li>统计需求开工顺序固定为：<strong>源字段取值分布 → 维度可关联 → 聚合 SQL</strong>；跳过第一步的统计页不要交付。</li><li>发现写入侧缺失时，把修复纳入本次范围并在交付说明单列一条「统计口径配套修复」，不要静默只改聚合逻辑。</li><li>页面/接口上对「未配置 / 未知」维度值显式兜底显示（如「未配置」），避免把数据缺失伪装成 0 值指标。</li></ol><h3 id="resolution-6" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-6" aria-label="Permalink to &quot;Resolution&quot;">​</a></h3><p>2026-09-07：QCM V2 feat-012 按此顺序核查，<code>LogInterceptor</code> 的 <code>statusFlag</code> 改为按响应判定（平台异常响应 <code>code != 0000</code> 记失败，第三方原始报文无 <code>code</code> 记成功），与统计接口同批交付。</p>',88)])])}const p=o(s,[["render",d]]);export{g as __pageData,p as default};
